use crate::*;
use schemars::schema_for;

/// Application ownership, declared beside each operation's typed contract.
/// Transports use this metadata for discovery; authorization stays on the leaf.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum ToolDomain {
    System,
    Project,
    Edit,
    Media,
    Analysis,
    Render,
    Catalog,
    Task,
    Observe,
    Plugin,
    Access,
    Workspace,
}

impl ToolDomain {
    pub const ALL: &'static [Self] = &[
        Self::System,
        Self::Project,
        Self::Edit,
        Self::Media,
        Self::Analysis,
        Self::Render,
        Self::Catalog,
        Self::Task,
        Self::Observe,
        Self::Plugin,
        Self::Access,
        Self::Workspace,
    ];

    pub const fn name(self) -> &'static str {
        match self {
            Self::System => "system",
            Self::Project => "project",
            Self::Edit => "edit",
            Self::Media => "media",
            Self::Analysis => "analysis",
            Self::Render => "render",
            Self::Catalog => "catalog",
            Self::Task => "task",
            Self::Observe => "observe",
            Self::Plugin => "plugin",
            Self::Access => "access",
            Self::Workspace => "workspace",
        }
    }

    pub const fn description(self) -> &'static str {
        match self {
            Self::System => "Discover host capabilities and supported operations.",
            Self::Project => {
                "Create, inspect, branch, restore and exchange editing projects and their history."
            }
            Self::Edit => "Plan and atomically commit timeline and content changes.",
            Self::Media => "Transfer, inspect, bind and repair immutable project media.",
            Self::Analysis => {
                "Analyze fixed sources and query reusable timecoded evidence without editing projects."
            }
            Self::Render => {
                "Preview fixed revisions, render output and inspect published output quality."
            }
            Self::Catalog => {
                "Discover and acquire approved fonts, sounds and image resources with source proofs."
            }
            Self::Task => {
                "Submit typed jobs through their application use cases, observe and cancel tasks, and inspect execution receipts."
            }
            Self::Observe => "Read authorized resources, project events and mutation history.",
            Self::Plugin => "Install, authorize and plan constrained editing plugins.",
            Self::Access => "Inspect access and authorization audit records.",
            Self::Workspace => "Owner-only database, storage and publication maintenance.",
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
pub struct ToolSpec {
    pub name: String,
    pub description: String,
    pub read_only: bool,
    pub input_schema: Value,
    pub output_schema: Value,
}

#[derive(Debug, Clone, Copy)]
pub struct ToolSummary {
    pub name: &'static str,
    pub description: &'static str,
    pub read_only: bool,
    pub domain: ToolDomain,
    pub action: &'static str,
}

fn spec<T: JsonSchema, R: JsonSchema>(name: &str, description: &str, read_only: bool) -> ToolSpec {
    ToolSpec {
        name: name.into(),
        description: description.into(),
        read_only,
        input_schema: serde_json::to_value(schema_for!(T)).expect("schema is JSON"),
        output_schema: serde_json::to_value(schema_for!(Response<R>)).expect("schema is JSON"),
    }
}

mod sealed {
    pub trait Sealed {}
}
/// A registered tool owns its name and associated request/response types.
pub trait Tool: sealed::Sealed {
    type Input: serde::Serialize + serde::de::DeserializeOwned + JsonSchema;
    type Output: serde::Serialize + serde::de::DeserializeOwned + JsonSchema;
    const NAME: &'static str;
    const READ_ONLY: bool;
    const DOMAIN: ToolDomain;
    const ACTION: &'static str;
}
macro_rules! tools {
    ($( $marker:ident: ($input:ty, $output:ty, $name:literal, $description:literal, $read_only:literal, $domain:ident, $action:literal) ),* $(,)?) => {
        $(
            pub struct $marker;
            impl sealed::Sealed for $marker {}
            impl Tool for $marker {
                type Input = $input;
                type Output = $output;
                const NAME: &'static str = $name;
                const READ_ONLY: bool = $read_only;
                const DOMAIN: ToolDomain = ToolDomain::$domain;
                const ACTION: &'static str = $action;
            }
        )*
        /// Typed in-process invocation generated from the public registry.
        /// This is not an additional wire envelope or a published schema.
        #[allow(clippy::large_enum_variant)]
        pub enum ToolRequest { $( $marker($input), )* }
        impl ToolRequest {
            pub fn decode(name: &str, value: Value) -> Result<Self, opencut_contracts::EditorError> {
                match name {
                    $( $name => serde_json::from_value(value).map(Self::$marker)
                        .map_err(|e| opencut_contracts::EditorError::new("INVALID_ARGUMENT", e.to_string())), )*
                    _ => Err(opencut_contracts::EditorError::new("NOT_FOUND", format!("Unknown operation: {name}"))),
                }
            }
            /// Compatibility adapter for the native facade during use-case migration.
            pub fn into_parts(self) -> Result<(&'static str, Value), opencut_contracts::EditorError> {
                match self { $( Self::$marker(input) => serde_json::to_value(input)
                    .map(|value| ($name, value))
                    .map_err(|e| opencut_contracts::EditorError::new("INTERNAL_ERROR", e.to_string())), )* }
            }
        }
        pub fn is_tool(name: &str) -> bool { matches!(name, $($name)|*) }
        pub fn tool_summaries() -> &'static [ToolSummary] {
            const SUMMARIES: &[ToolSummary] = &[$(ToolSummary {
                name: $name,
                description: $description,
                read_only: $read_only,
                domain: ToolDomain::$domain,
                action: $action,
            }),*];
            SUMMARIES
        }
        pub fn tool_spec(name: &str) -> Option<ToolSpec> {
            match name {
                $($name => Some(spec::<$input, $output>($name, $description, $read_only)),)*
                _ => None,
            }
        }
        /// Generate domain inputs with one shared definition table. All transport
        /// schemas remain derived from these exact registered request types.
        pub fn tool_input_schema(name: &str, generator: &mut schemars::SchemaGenerator) -> Option<Value> {
            match name {
                $($name => Some(generator.subschema_for::<$input>().to_value()),)*
                _ => None,
            }
        }
        pub fn tool_specs() -> Vec<ToolSpec> {
            vec![$(spec::<$input, $output>($name, $description, $read_only)),*]
        }
    }
}
